#!/bin/bash
# keep_count <conf>: print keep from the config file (default 3 if missing/invalid).
keep_count() {
  local k
  k=$(sed -n 's/^keep=\([0-9][0-9]*\)$/\1/p' "$1" 2>/dev/null | tail -n 1)
  echo "${k:-3}"
}

# prune_local <dir> <name> <keep>: delete name.N with N > keep.
prune_local() {
  local dir=$1 name=$2 keep=$3 f n
  for f in "$dir/$name".*; do
    [ -e "$f" ] || continue
    n=${f##*/"$name".}
    case $n in ''|*[!0-9]*) continue ;; esac
    [ "$n" -gt "$keep" ] && rm -f -- "$f"
  done
}

# prune_archive <archive dir> <name> <keep>: keep the newest <keep> name.<YYYYMMDD>, delete the rest.
prune_archive() {
  local dir=$1 name=$2 keep=$3 f s
  for f in "$dir/$name".*; do
    s=${f##*/"$name".}
    case $s in ''|*[!0-9]*) continue ;; esac
    echo "$s"
  done | sort -r | tail -n +$((keep + 1)) | while read -r s; do
    rm -f -- "$dir/$name.$s"
  done
}

