#!/bin/bash
# prune_local <dir> <name> <keep>: delete name.N (N numeric) beyond the newest <keep> generations (name.1 is newest).
prune_local() {
  local dir=$1 name=$2 keep=$3 f n
  for f in "$dir/$name".[0-9]*; do
    [ -e "$f" ] || continue
    n=${f##*.}
    case $n in *[!0-9]*) continue ;; esac
    [ "$n" -gt "$keep" ] && rm -f "$f"
  done
}

# prune_archive <archive dir> <name> <keep>: keep only the <keep> newest name.<stamp> (stamp = 8 digits, sorts by date).
prune_archive() {
  local archive=$1 name=$2 keep=$3 f
  ls "$archive" | grep "^$name\.[0-9]\{8\}$" | sort -r | tail -n +"$((keep + 1))" |
    while read -r f; do rm -f "$archive/$f"; done
}

